INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.121.0',
  '2026-10-19',
  'Медиатека: ссылок на музыку можно дать сразу несколько',
  E'Окно «⬇ По ссылке» теперь принимает не один адрес, а сколько нужно — по одному в строке. Ссылки встают в очередь и скачиваются по одной, в том порядке, в котором вы их набрали: сидеть и ждать каждую, чтобы вставить следующую, больше не надо.\n\nОчередь видна на вкладке «Задачи»: что качается сейчас и что ждёт. Ненужную ссылку можно снять («✖ Снять»), можно снять все сразу. «✖ Остановить» у самой задачи останавливает всю очередь.\n\nЕсли одна ссылка не открылась, остальные всё равно скачаются — причина останется строкой в отчёте задачи, а в конце будет видно, сколько не вышло. Ссылки можно докладывать и пока идёт закачка: они просто встанут в хвост. Даже если агент в это время занят другой работой — скажем, перекодированием, — он возьмётся за них, как освободится.\n\nОчередь не теряется при перезапуске мини-сервера: набранные адреса лежат на диске, и после включения агент доберёт их сам.\n\nИмя скачанного файла снова такое же, как у всей остальной музыки в медиатеке: название страницы и «[идентификатор]» в конце. В прошлой версии хвост был убран — зря, новые треки выделялись среди старых.',
  E'ytdlp.go: POST /api/admin/fetch принимает {urls[]} (и по-прежнему {url}) — адреса разделяются переводом строки или пробелом, которых внутри адреса быть не может; POST /api/admin/fetch/drop {id|all} снимает из очереди; GET /api/admin/fetch отдаёт ещё queue и busy. На странице поле на несколько строк — askLines: Enter в нём перевод строки, «⬇ Скачать» кнопкой или Ctrl+Enter, стрелка выводит из поля только с первой и последней строки (иначе на пульте из него не уйти), modalAnswer читает input и textarea.\n\nОчередь — fetchStore поверх fetch-queue.json в кэше, а не память задачи: агента перезапускают деплоем, и десяток набранных руками адресов терять обидно. Поднимает её fetchWorker раз в 30 с — он же берётся за дело, если ссылки положили во время другой задачи, поэтому занятость это не отказ, а поле busy в ответе: иначе набрать очередь во время перекодирования было бы нельзя. Одна задача на всю очередь (taskStore по-прежнему одна задача разом), в отчёте строка на ссылку; fetchDrain берёт голову, качает, при неудаче считает и идёт дальше, bad == at возвращает последнюю ошибку (у одной ссылки поведение прежнее). Отмена снимает всю очередь: иначе fetchWorker поднял бы её через полминуты и «Остановить» выглядело бы сломанным. Полоска у очереди считает ссылки (done = at-1, total = at+left), проценты уходят в подпись; total пересчитывается каждый раз, потому что очередь может расти на ходу.\n\nПовтор того же адреса в ту же папку не встаёт, предел 100. Папка перед каждой закачкой сверяется заново (os.Stat + inRoots): пока ссылка ждала, её могли переименовать или удалить. Путь к yt-dlp тоже берётся заново — его могли поставить или обновить, пока ссылка стояла. sweepFetchTemp на старте сносит временные папки fetch-*: при убийстве процесса defer в fetchAudio не срабатывает.\n\nИмя файла вернулось к шаблону yt-dlp: -o "%(title).150B [%(id)s].%(ext)s". Вся музыка в медиатеке собрана им же (101 файл вида «Песня [id].m4a»), и новое не должно выделяться; тест подставляет шаблон вместо yt-dlp и проверяет имя на диске, а не ключ.\n\nДевять новых тестов на подменённом бинарнике и очереди: порядок закачек, повтор, одна битая из трёх, отмена с очисткой, жизнь после перезапуска, снятие по id и целиком, разбор многострочного поля, ручка с несколькими ссылками, ожидание при занятом агенте, уборка временных папок. Проверено вживую на res-i3.'
);
-- +goose StatementEnd

